	private void degisiklikleriKaydetToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (lb_kullanicilar.SelectedValue != null)
		{
			KullaniciParametreKaydet();
		}
	}

	private void kullanıcıSilToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (lb_kullanicilar.SelectedValue == null)
		{
			return;
		}
		bool flag = true;
		if (DegisiklikVar)
		{
			switch (MessageBox.Show("Kayıt edilmemiş değişiklikler var kaydetmek istiyor musunuz?", "Onaylama", MessageBoxButtons.YesNoCancel, MessageBoxIcon.Question))
			{
			case DialogResult.Yes:
				KullaniciParametreKaydet();
				flag = true;
				break;
			case DialogResult.No:
				flag = true;
				break;
			case DialogResult.Cancel:
				flag = false;
				break;
			}
		}
		string text = lb_kullanicilar.SelectedValue.ToString();
		if (flag)
		{
			DialogResult dialogResult = MessageBox.Show(text + " kullanıcısını silmek istediğinize emin misiniz?", "Onaylama", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
			if (dialogResult != DialogResult.Yes)
			{
				_ = 7;
				return;
			}
			AndroidKullaniciData.KullaniciSil(_mikrouygulamabilgileri.baglantibilgileri, _mikrouygulamabilgileri.MikroFirmaDBName, text);
			KullanicilariListele();
		}
	}

	private void kullaniciEkleToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (DegisiklikVar)
		{
			switch (MessageBox.Show("Kayıt edilmemiş değişiklikler var kaydetmek istiyor musunuz?", "Onaylama", MessageBoxButtons.YesNoCancel, MessageBoxIcon.Question))
			{
			case DialogResult.Yes:
				KullaniciParametreKaydet();
				break;
			case DialogResult.Cancel:
				return;
			}
		}
		ForaAndroidKullaniciEkle foraAndroidKullaniciEkle = new ForaAndroidKullaniciEkle(_mikrouygulamabilgileri);
		foraAndroidKullaniciEkle.ShowDialog();
		if (foraAndroidKullaniciEkle.DialogResult == DialogResult.OK)
		{
			Parametreler parametreler;
			if (foraAndroidKullaniciEkle._KoyalanacakKullanici == "YOK")
			{
				parametreler = ParametrelerDefault.MobilKullanici(foraAndroidKullaniciEkle._KullaniciAdi);
			}
			else
			{
				Parametreler parametreler2 = ParametrelerDefault.MobilKullanici(foraAndroidKullaniciEkle._KoyalanacakKullanici);
				ParametreData.ParametreOku(_mikrouygulamabilgileri.baglantibilgileri, _mikrouygulamabilgileri.MikroFirmaDBName, parametreler2, "akilli", foraAndroidKullaniciEkle._KoyalanacakKullanici, "", "");
				foreach (Parametre item in parametreler2.ParametreListesi)
				{
					item.EskiID = 0;
					item.IDGuid = null;
					item.ParametreUser = foraAndroidKullaniciEkle._KullaniciAdi;
				}
				parametreler = parametreler2;
			}
			parametreler._GetParametre("Sifre")._SetString = GenelUtilityWin.EncryptText("drjbq8777!#45", foraAndroidKullaniciEkle._Sifre, useHashing: true);
			parametreler._GetParametre("CariPersonelKodu")._SetString = foraAndroidKullaniciEkle._CariPersonelKodu;
			parametreler._GetParametre("CariKodu")._SetString = foraAndroidKullaniciEkle._CariKodu;
			parametreler._GetParametre("StokReyonKodu")._SetString = foraAndroidKullaniciEkle._Tanimli_Stok_Reyon_Kodu;
			parametreler._GetParametre("StokSecimiDefaultAktifGrup")._SetString = foraAndroidKullaniciEkle._Stok_Secimi_Varsayilan_aktif_Grup;
			ParametreData.ParametreYaz(_mikrouygulamabilgileri.baglantibilgileri, _mikrouygulamabilgileri.MikroFirmaDBName, parametreler);
			KullanicilariListele();
			lb_kullanicilar.SelectedItem = foraAndroidKullaniciEkle._KullaniciAdi;
		}
		foraAndroidKullaniciEkle.Dispose();
		foraAndroidKullaniciEkle = null;
	}

	private void dosyayaYazToolStripMenuItem_Click(object sender, EventArgs e)
	{
		if (DegisiklikVar)
		{
			switch (MessageBox.Show("Kayıt edilmemiş değişiklikler var kaydetmek istiyor musunuz?", "Onaylama", MessageBoxButtons.YesNoCancel, MessageBoxIcon.Question))
			{
			case DialogResult.Yes:
				KullaniciParametreKaydet();
				break;
			case DialogResult.Cancel:
				return;
			}
		}
		try
		{
			SaveFileDialog saveFileDialog = new SaveFileDialog();
			saveFileDialog.Filter = "Fora parametreler|*.fpt|Tüm dosyalar|*.*";
			if (saveFileDialog.ShowDialog() == DialogResult.OK)
			{
				FileStream fileStream = new FileStream(saveFileDialog.FileName, FileMode.CreateNew);
				_kullaniciparametreleri.KullanimAlani = "akilli";
				Parametreler.WriteToStream(_kullaniciparametreleri, fileStream, 2);
				fileStream.Close();
				fileStream.Dispose();
			}
		}
		catch
		{
			MessageBox.Show("Dosya oluşturulamadı!");
		}
	}

	private void dosyadanOkuToolStripMenuItem_Click(object sender, EventArgs e)
	{
		OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.Filter = "Fora parametreler|*.fpt|Tüm dosyalar|*.*";
		if (openFileDialog.ShowDialog() != DialogResult.OK)
		{
			return;
		}
		TextSor textSor = new TextSor("Kullanıcı adı", "DEVAM");
		if (textSor.ShowDialog() != DialogResult.OK)
		{
			return;
		}
		foreach (string item in lb_kullanicilar.Items)
		{
			if (item == textSor.te_cevap.Text)
			{
				MessageBox.Show("Bu kullanıcı adı daha önce kullanılmış. İşlem tamamlanamadı!");
				return;
			}
		}
		FileStream fileStream = new FileStream(openFileDialog.FileName, FileMode.Open);
		Parametreler parametreler = Parametreler.ReadFromStream(fileStream);
		fileStream.Close();
		fileStream.Dispose();
		if (parametreler.KullanimAlani != "akilli")
		{
			MessageBox.Show("Dosya uygun değil. İşlem tamamlanamadı!");
			return;
		}
		foreach (Parametre item2 in parametreler.ParametreListesi)
		{
			item2.EskiID = 0;
			item2.IDGuid = null;
			item2.ParametreUser = textSor.te_cevap.Text;
		}
		ParametreData.ParametreYaz(_mikrouygulamabilgileri.baglantibilgileri, _mikrouygulamabilgileri.MikroFirmaDBName, parametreler);
		KullanicilariListele();
		lb_kullanicilar.SelectedItem = textSor.te_cevap.Text;
	}

